  A.Below(x, l, h);
  if y < l {
    A.Below(y, l, h);
  } else if y <= h {
    A.Within(y, l, h);
  } else {
    A.Above(y, l, h);
  }
} else if x <= h {
  A.Within(x, l, h);
  if y <= h {
    A.Within(y, l, h);
  } else {
    A.Above(y, l, h);
  }
} else {
  A.Above(x, l, h);
  A.Above(y, l, h);
